kwik (As, Cd, Co, Cr, Cu, Mn, Ni, Pb, Sb, Se, Tl,
V, Zn)', NULL, NULL, 'metalenenmetalloidenmetuitzonderingvankwik', NULL, NULL) ON CONFLICT DO NOTHING;
uitgedrukt als no2', NULL, NULL, 'Nox_NO2', NULL, NULL) ON CONFLICT DO NOTHING;

COMMIT;
